            macroB: true,
            periodMacroB: 6.9,
            macroRoughB: 0.2,
            stain: [0.42, -0.22],
            stainTint: 10133644,
            stainRange: [0.64, 0.96],
            instUv: 0.8,
            instTint: 0.07,
