            const md = microDetail(mic, i);
            const tone = 0.94 + trowel[i] * 0.12 + md * 0.06 + (grain[i] - 0.5) * 0.04 + (patchM[i] - 0.5) * 0.24;
            f.set(i, _b.r * tone, _b.g * tone, _b.b * tone);
