            const rough = clamp2(microRough(mic, i, 0.9) + (trowel[i] - 0.5) * 0.1 + crack * 0.06, 0.62, 0.99);
            const ao = 1 - crack * 0.22 - (1 - trowel[i]) * 0.08;
