            macroTex,
            period: 11.7,
            strength: 0.42,
            periodB: 3.8,
            strengthB: 0.27,
            macroWarm: 16770760,
            macroCool: 14672608,
            macroTint: 0.42,
            macroRough: 0.24,
            // moss and rain run down the pitch, i.e. along V, from the ridge
            streak: [0.5, 0.06, 0.05, 0.14],
            // moss banks: darker, greener, much rougher, in patches with an edge
            macroB: true,
            periodMacroB: 6.1,
            macroRoughB: 0.2,
            stain: [0.46, -0.26],
            stainTint: 9278564,
            stainRange: [0.66, 0.97],
            instUv: 0.85,
            instTint: 0.13,
