            g.fillRect(0, hh * 0.8, size, hh * 0.2);
            g.fillStyle = "#f5e2b0";
            g.font = `700 ${hh * 0.13}px "Helvetica Neue", Helvetica, Arial, sans-serif`;
            g.textAlign = "center";
            g.textBaseline = "middle";
            g.letterSpacing = "6px";
            g.fillText("NITRO  \xB7  AMALFI OIL  \xB7  BOOST CO.  \xB7  MARINA", size / 2, hh * 0.9);
            g.fillStyle = "#f2ece0";
