          const bank = cl.bank[i];
          const amt = ss(0.209, 0.314, Math.abs(bank));
          if (amt <= 0) return 0;
          const hw = cl.half[i];
          const t = Math.min(1, (bank >= 0 ? L : -L) / hw);
          if (t <= APRON_T0) return 0;
